sheet.css:
.pk{--g:#fafafa;--ink:#111;--grey:#6b6b6b;--rule:#e4e4e4;--accent:#c8462c;
  background:var(--g);color:var(--ink);font:400 17px/1.6 ui-sans-serif,system-ui,sans-serif}
[data-theme=dark].pk,[data-theme=dark] .pk{--g:#0f0f0f;--ink:#f0f0f0;--grey:#9a9a9a;--rule:#242424}
.stage.pk{--page:var(--g);background:var(--g)}
.pk h3,.pk h4{font-weight:300;letter-spacing:-.02em;margin:0;color:var(--ink)}
.pk p{margin:0;max-width:60ch}
.muted{color:var(--grey)}
.rule{width:32px;height:1px;background:var(--ink)}
.hair{border-top:1px solid var(--rule)}
.pk-btn{font:400 16px/1 inherit;background:var(--ink);color:var(--g);border:1px solid var(--ink);
  border-radius:2px;padding:12px 20px;cursor:pointer;transition:opacity .16s}
.pk-btn:hover{opacity:.7}
.pk-btn:focus-visible{outline:2px solid var(--ink);outline-offset:3px}
.pk-btn.sec{background:transparent;color:var(--ink)}
.pk-btn[disabled]{opacity:.35;cursor:not-allowed}
.f-hover{opacity:.7}
.f-focus{outline:2px solid var(--ink);outline-offset:3px}
.pk-field{width:100%;background:transparent;color:var(--ink);border:0;border-bottom:1px solid var(--ink);
  padding:8px 0;font:400 17px/1.4 inherit}
.pk-field:focus-visible{outline:2px solid var(--ink);outline-offset:3px}
.pk-label{display:block;font-size:13px;color:var(--grey);margin-bottom:4px}
.pk-err{margin-top:8px;font-size:14px;color:var(--ink)}
.pk-err b{color:var(--accent)}
.pk-nav{display:flex;align-items:center;gap:26px;padding-bottom:14px;border-bottom:1px solid var(--rule)}
.pk-nav a{color:var(--grey);text-decoration:none;font-size:15px;padding:6px 2px;display:inline-block}
  /* padding is not decoration here: 15px x 1.6 line-height = 23.99px, 0.01px under WCAG 2.5.8 */
.pk-nav a[aria-current]{color:var(--ink)}
.pk-nav .sp{flex:1}
table.pk-t{width:100%;border-collapse:collapse;font-size:15px}
table.pk-t th{text-align:left;color:var(--grey);font-weight:400;font-size:13px;padding:0 0 12px}
table.pk-t td{padding:14px 0;border-top:1px solid var(--rule)}
.pk-scrim{background:rgba(0,0,0,.4);padding:40px 18px;display:flex;justify-content:center}
.pk-dialog{background:var(--g);padding:28px;max-width:360px;width:100%}
.pk-empty{padding:36px;text-align:center;border-top:1px solid var(--rule);border-bottom:1px solid var(--rule)}
.pk-skel{height:12px;background:var(--rule);margin-bottom:10px}
.swatch{border:1px solid var(--rule,#e4e4e4);height:54px}
